#include <stdio.h>

#define MAXN 200005

int N, M;
long long bitA[MAXN];
long long bitB[MAXN];

static inline void update(int idx, long long valA, long long valB) {
    for (; idx <= N + 1; idx += idx & -idx) {
        bitA[idx] += valA;
        bitB[idx] += valB;
    }
}

static inline void range_update(int L, int R, long long A, long long B) {
    if (L > R) return;
    update(L, A, B);
    update(R + 1, -A, -B);
}

static inline long long query(int idx) {
    long long sumA = 0;
    long long sumB = 0;
    int i = idx;
    for (; i > 0; i -= i & -i) {
        sumA += bitA[i];
        sumB += bitB[i];
    }
    return sumA + sumB * idx;
}

int main() {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int q = 0; q < M; ++q) {
        int type;
        if (scanf("%d", &type) != 1) break;

        if (type == 1) {
            long long i, V;
            scanf("%lld %lld", &i, &V);
            long long L = i;
            long long R = i + V - 1;
            if (R > N) R = N;
            long long A = V + i;
            long long B = -1;
            range_update((int)L, (int)R, A, B);
        } else if (type == 2) {
            long long i, V;
            scanf("%lld %lld", &i, &V);
            long long L = i - V + 1;
            if (L < 1) L = 1;
            long long R = i;
            long long A = V - i;
            long long B = 1;
            range_update((int)L, (int)R, A, B);
        } else if (type == 3) {
            int i;
            scanf("%d", &i);
            printf("%lld\n", query(i));
        }
    }

    return 0;
}
